import json
d = json.load(open('factors/mom_10d_skip5.json'))
def show(obj, indent=0, maxdepth=2):
    if maxdepth <= 0: return
    if isinstance(obj, dict):
        for k,v in obj.items():
            if isinstance(v,(dict,list)):
                print(' '*indent + str(k)+':')
                show(v, indent+2, maxdepth-1)
            else:
                s=str(v)
                print(' '*indent + str(k)+': '+s[:100])
    elif isinstance(obj, list):
        print(' '*indent + f'[list len={len(obj)}]')
        if obj: show(obj[0], indent+2, maxdepth-1)
show(d, 0, 3)
"

